let comparisonIds = [];
const comparisonKey = 'happiness-plaza-unit-comparison';
try {
  const saved = JSON.parse(localStorage.getItem(comparisonKey) || '[]');
  if (Array.isArray(saved)) comparisonIds = [...new Set(saved.filter(id=>byId.has(id)))].slice(0,3);
} catch {}
function updateComparison() {
  document.querySelectorAll('.compare-count').forEach(el => el.textContent = comparisonIds.length.toLocaleString('ar-EG'));
  try {localStorage.setItem(comparisonKey, JSON.stringify(comparisonIds));} catch {}
  document.querySelectorAll('[data-compare-unit]').forEach(button=>{
    const on=comparisonIds.includes(button.dataset.compareUnit);
    button.disabled = !on && comparisonIds.length >= 3;
    button.setAttribute('aria-pressed',String(on));
    button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  });
}
function makeCompareButton(u) {
  const button = btn('', ()=>{
    const selected=comparisonIds.includes(u.id);
    if (selected) comparisonIds=comparisonIds.filter(id=>id!==u.id);
    else if (comparisonIds.length<3) comparisonIds.push(u.id);
    updateComparison();
  },'secondary');
  button.dataset.compareUnit=u.id;
  const on=comparisonIds.includes(u.id);
  button.disabled=!on && comparisonIds.length>=3;
  button.setAttribute('aria-pressed',String(on));
  button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  return button;
}
function openComparison(){
  if(dialog.open && document.getElementById('dialogtitle').textContent==='مقارنة الوحدات') body.replaceChildren();
  else openBox('مقارنة الوحدات');
  if(!comparisonIds.length) {
    body.append(el('p','','افتح رقم محل من المخطط واختر «أضف للمقارنة». يمكنك عرض بيانات ثلاث وحدات جنبًا إلى جنب.'));
    const backToMap=href('افتح المخطط','#plan/'+(shownUnit?.f||fl));
    backToMap.addEventListener('click',()=>dialog.close());
    body.append(backToMap);return;
  }
  const items=comparisonIds.map(id=>byId.get(id));
  const scroller=el('div','comparison-scroll'), table=el('table','comparison');
  table.setAttribute('aria-label','بيانات الوحدات المختارة');
  const head=table.createTHead().insertRow();
  head.append(el('th','','الوحدة'));
  for(const u of items){const th=el('th');th.scope='col';const link=href(u.pending?u.title:u.id,'#unit/'+u.id,'under');link.addEventListener('click',()=>dialog.close());th.append(link);head.append(th);}
  const rows=[['الدور',u=>FLOORS[u.f]],['النشاط',u=>u.cat],['مساحة التأجير',u=>fmt(u.area)],['المساحة الإضافية',u=>u.extra?u.elab+' · '+fmt(u.extra):'غير مبيّنة'],['التوافر',u=>u.status]];
  const tb=table.createTBody();
  for(const [title,get] of rows){const row=tb.insertRow(),th=el('th','',title);th.scope='row';row.append(th);for(const u of items)row.append(el('td','',get(u)));}
  const row=tb.insertRow();row.append(el('th','','تعديل الاختيارات'));
  for(const u of items){
    const cell=el('td'), remove=btn('إزالة',()=>{comparisonIds=comparisonIds.filter(id=>id!==u.id);updateComparison();openComparison();$('#close').focus();},'tool');
    remove.setAttribute('aria-label','إزالة '+u.id+' من المقارنة');cell.append(remove);row.append(cell);
  }
  scroller.append(table);body.append(scroller);
  const back=href('اختر وحدة أخرى من المخطط','#plan/'+(shownUnit?.f||fl));
  back.addEventListener('click',()=>dialog.close());
  body.append(back);
}
