let lastRouteURL, lastBaseURL;
function dispatchRoute(force=false){
 if(!force&&lastRouteURL===location.href)return;
 lastRouteURL=location.href;
 const base=new URL(location.href);
 base.searchParams.delete('doc');
 base.searchParams.delete('page');
 if(force||lastBaseURL!==base.href){
   lastBaseURL=base.href;
   if(activeChapter!==-1&&currentRoute()!==chapterStops[activeChapter][0])closePresentation();
   route();
 }
 syncDocument();
}
